(x, y, t) => {
  const cx = 240, cy = 120;
  const wx1 = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const wy1 = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const wx2 = Math.sin((x+wx1)*0.035-t*0.5)*8 + Math.cos((y+wy1)*0.028+t*0.4)*6;
  const wy2 = Math.cos((y+wy1)*0.032+t*0.45)*8 + Math.sin((x+wx1)*0.025-t*0.38)*6;
  const sx = x+wx1+wx2, sy = y+wy1+wy2;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,0.7],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,0.6],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,0.8],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,0.5],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,0.75],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,0.65],
    [80+Math.sin(t*0.7+3)*110,40+Math.cos(t*0.3+1)*60,0.11,1.8,0.55],
    [400+Math.cos(t*0.45+2)*70,200+Math.sin(t*0.65+4)*50,0.05,2.8,0.85]
  ];
  let aS=0,iS=0,mS=0;
  for(const[sX,sY,f,sp,m]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp);
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5);
    mS+=Math.sin(d*f*0.4-t*sp*0.3+2.8)*m;
  }
  const act=aS/8,inh=iS/8,mod=mS/8;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2)+Math.sin(dist*0.06-ang*2+t*0.8))*0.27;
  const pulse=Math.sin(dist*0.03-t*3)*Math.exp(-dist*0.005)*0.5;
  const voronoi=()=>{
    let md=99,v=0;
    for(let i=0;i<8;i++){
      const vx=80+i*55+Math.sin(t*0.4+i*1.3)*30,vy=40+((i*37)%200)+Math.cos(t*0.35+i*0.9)*25;
      const d=Math.sqrt((sx-vx)**2+(sy-vy)**2);
      if(d<md){md=d;v=Math.sin(d*0.2+t+i);}
    }
    return Math.tanh(v*1.5)*0.4;
  };
  const vor=voronoi();
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const rd1=Math.tanh((act-inh*0.7+bg*0.3+spiral+pulse)*2.2);
  const rd2=Math.tanh((inh*0.8-act*0.5+vor+mod)*1.8);
  const reaction=rd1*0.65+rd2*0.35;
  const blend=reaction*0.6+cell*0.15+vor*0.15+bg*0.1;
  const v=blend*0.5+0.5;
  const tShift=Math.sin(t*0.2)*0.08;
  const pal=[
    [5,10,45],[12,35,85],[8,75,105],[15,130,125],
    [45,165,140],[140,185,80],[200,180,55],
    [215,130,60],[190,75,65],[130,40,55],
    [70,18,45],[25,12,35],[5,10,45]
  ];
  const idx=Math.max(0,Math.min(1,v+tShift))*(pal.length-1);
  const i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.85+Math.sin(reaction*Math.PI)*0.15+Math.abs(rd2)*0.1;
  const edgeR=Math.abs(reaction)>0.65?1.2:1.0;
  const edgeG=Math.abs(rd2)>0.6?1.15:1.0;
  const glow=Math.max(0,1-dist*0.004)*0.15+Math.max(0,reaction)*0.1;
  return[
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edgeR+glow*30))|0,
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edgeG+glow*20))|0,
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*1.05+glow*40))|0
  ];
}
